window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-adenomiose"]={"block":"anki:ginecologia-adenomiose","label":"Anki · Adenomiose","count":44,"questions":[{"id":"anki-ginecologia-adenomiose-2451782c242147ea","number":"0201g","sourceNumber":"0201g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher, 44 anos de idade, 3G 3P, apresenta dismenorreia progressiva há 2 anos, associada a aumento do volume menstrual e dispaurenia, há 8 meses, dificultando o relacionamento sexual. Ao exame: útero aumentado 2 vezes de tamanho, consistência amolecida. US pélvico: útero heterogêneo, focos hiperecogênicos puntiformes em meio a trama miometrial, espessura endometrial 8 mm, volume uterino: 178 ml, ovários sem alterações. A conduta mais adequada é:","options":{"A":"prescrever danazol via oral.","B":"realizar histerectomia sub-total.","C":"prescrever análogo de GnRH subcutâneo.","D":"realizar embolização das artérias uterinas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551495","ankiGuid":"K!xKXIm?c{"},{"id":"anki-ginecologia-adenomiose-188becd034336bea","number":"0202g","sourceNumber":"0202g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente com 39 anos, sem filhos, vem à consulta referindo fluxo menstrual aumentado nos últimos três meses. Traz ecografia transvaginal sugestiva de adenomiose leve e difusa e hemoglobina de 12,2g/dL. Qual a conduta inicial correta no acompanhamento dessa paciente?","options":{"A":"Realizar calendário menstrual, reavaliar em 6 meses e suplementação preventiva de ferro.","B":"Prescrever análogo do GnRh por 6 meses e suplementação injetável de ferro.","C":"Internar para uso de suplementação de ferro injetável e tratamento cirúrgico (histerectomia)","D":"Prescrever análogo do GnRh, suplementação injetável de ferro e reavaliar em 30 dias."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551522","ankiGuid":"rOA?ydk=G_"},{"id":"anki-ginecologia-adenomiose-97bef67c9d53386e","number":"0203g","sourceNumber":"0203g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paula, 33 anos, G0P0, hipertensa, com queixa de dismenorreia e fluxo menstrual volumoso com coágulos. USG transvaginal revelando útero com discreto aumento de volume, espessamento miometrial assimétrico em parede posterior com áreas de sombras acústicas e pequenas áreas anecoicas subendometriais. Considerando o principal diagnóstico, qual conduta mais indicada?","options":{"A":"SIU de levonorgestrel.","B":"Adesivo contraceptivo.","C":"Análogo do GnRH por 3 anos.","D":"Histerectomia total laparoscópica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551523","ankiGuid":"Jr6[N`qh~)"},{"id":"anki-ginecologia-adenomiose-c16fb6934531481d","number":"0204g","sourceNumber":"0204g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 42 anos de idade, G3P3, queixa-se de aumento da duração e quantidade do fluxo menstrual há oito meses. Refere também dismenorreia intensa. O exame físico é compatível com útero discretamente aumentado de volume. A ultrassonografia está representada na imagem a seguir.\n\nNesse caso, qual é a hipótese diagnóstica mais provável?","options":{"A":"Leiomiomas do útero.","B":"Adenomiose","C":"Endometriose pélvica.","D":"Câncer do endométrio."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":["question_bank/media/ginecologia-adenomiose/paste-91344f99f08acb6fc75523caae5e291186bf9dbd.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551524","ankiGuid":"mEfopD2>|F"},{"id":"anki-ginecologia-adenomiose-5694f4336fc289a6","number":"0205g","sourceNumber":"0205g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A.M.S., 44 anos GII/PII/AO 2PC, laqueadura tubária, encontra-se em acompanhamento ginecológico por dismenorreia importante associada a aumento de fluxo menstrual surgido nos últimos anos, com caráter progressivo. Realizou exames com RM, apresentando útero globoso com aumento de volume (210 cm³), assimetria de paredes uterinas, heterogeneidade difusa e cistos miometriais. Diante do quadro, qual a hipótese diagnóstica e a primeira linha de conduta terapêutica?","options":{"A":"Adenomiose; Dispositivo intrauterino de levonorgestrel","B":"Miomatose uterina; Histerectomia total","C":"Adenomiose; Histerectomia total","D":"Miomatose uterina; Contraceptivos hormonais"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551528","ankiGuid":"BGQ&yGwMrq"},{"id":"anki-ginecologia-adenomiose-fb5b9b53bedc5cbc","number":"0206g","sourceNumber":"0206g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A uma paciente com suspeita clínica e ultrassonográfica de adenomiose foi solicitada a realização de uma histeroscopia, que demonstrou cavidade uterina normal e endométrio de aspecto proliferativo. Realizou, também, uma biópsia de endométrio em parede posterior. Com base nesse caso hipotético, assinale a alternativa correta.","options":{"A":"Se a biópsia revelar ausência de apoptose, o diagnóstico de adenomiose estará caracterizado.","B":"Se a biópsia confirmar tratar-se de endométrio proliferativo, o diagnóstico será o de adenomiose.","C":"O resultado esperado do exame anatomopatológico é o de hiperplasia endometrial sem atipias.","D":"A confirmação de adenomiose se dá com o exame anatomopatológico de endométrio proliferativo e a dosagem sérica de CA 125 menor que 35 U/ml.","E":"A biópsia endometrial não tem relevância para o diagnóstico de adenomiose."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551531","ankiGuid":"LC5;DDM)nz"},{"id":"anki-ginecologia-adenomiose-7c9220596b16a6e0","number":"0207g","sourceNumber":"0207g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"M.R.F., feminino, 27 anos, apresenta queixa de sangramento menstrual volumoso, durante período menstrual, e dismenorreia. Ao exame físico, apresenta útero aumentado difusamente e doloroso à palpação. Foi realizada uma ultrassonografia transvaginal, que evidenciou um miométrio heterogêneo e eco endometrial mal definido. Com base nos achados clínicos e ultrassonográficos, assinale a principal hipótese diagnóstica.","options":{"A":"Endometriose.","B":"Câncer de endométrio.","C":"Leiomioma.","D":"Adenomiose.","E":"Pólipo endometrial."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551532","ankiGuid":"hr73dx%*|?"},{"id":"anki-ginecologia-adenomiose-701eeeee7a98cab4","number":"0208g","sourceNumber":"0208g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher, 35 anos, G3P2A0, três cesáreas prévias, com história de sangramento uterino de 9 dias de duração, com intervalo cíclico mensal regular e de grande volume que extravasa do absorvente, desde última cesárea ha8 anos. Associado quadro de cólicas incapacitantes em baixo ventre, progressiva, que intensifica nos primeiros 3 dias de fluxo necessitando de AINEs. Refere anemia crônica e fraqueza. Realizou ultrassonografia pélvica transvaginal que excluiu a possibilidade de leiomiomas e mostrou um útero aparentemente normal. Assinale a assertiva correta que corresponde à causa mais provável do sangramento uterino anormal.","options":{"A":"Endometrite.","B":"Adenomiose.","C":"Coagulopatia.","D":"Anovulação crônica."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551535","ankiGuid":"b7)xV&`{}f"},{"id":"anki-ginecologia-adenomiose-e1faf22df581414a","number":"0209g","sourceNumber":"0209g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 32 anos refere dismenorréia intensa e sangramento vaginal intenso durante o período menstrual. Nega: uso de medicamentos e traumas. Exame físico: hipocorada 2+/4, PA= 90/60 mmHg, pulso= 76 pulsações por minuto. Exame especular e toque vaginal bimanual sem alterações. Ausência de lesões em órgãos genitais externos. Exames complementares: Beta-HCG negativo (gonadotrofina coriônica humana), hemoglobina= 8.2 g/dl, plaquetas= 250 000 / mm3, ressonância magnética da pelve mostrando zona juncional espessada, sem outras alterações. Dentre as alternativas abaixo o diagnóstico mais provável é:","options":{"A":"Neoplasia de endométrio","B":"Espessamento endometrial","C":"Miomatose uterina","D":"Pólipo endometrial","E":"adenomiose"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551536","ankiGuid":"hX<}(Y2HXH"},{"id":"anki-ginecologia-adenomiose-750477ccdd9fb98a","number":"0210g","sourceNumber":"0210g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente de 32 anos, sem atividade sexual há 1 ano, vem à consulta com queixa de sangramento menstrual que aumentou nos últimos 6 meses, associado a cólicas. Ciclos regulares a cada 30 dias, com 7 dias de sangramento. Já engravidou 2 vezes e realizou 2 cesarianas. Ao exame apresenta-se normocorada, genitais externos e internos normais. Citopatológico normal. Ultrassonografia transvaginal mostra útero com volume de 132 cc, nódulo sugestivo de mioma, localizado em parede posterior medindo 42x35mm, subseroso. Endométrio com 12 mm de espessura, homogêneo. Ovários normais e fundo de saco livre. Assinale a alternativa correta:","options":{"A":"O útero está com volume normal para a paridade.","B":"O endométrio está muito espesso para qualquer fase do ciclo menstrual.","C":"O mioma apresentado justifica o sangramento menstrual aumentado.","D":"O melhor tratamento para esse mioma seria a histeroscopia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551537","ankiGuid":"DKBTX9I*u]"},{"id":"anki-ginecologia-adenomiose-93718ea6c1bd39ef","number":"0211g","sourceNumber":"0211g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente de 37 anos, nuligesta com queixa de dismenorreia progressiva há 3 anos e sangramento menstrual excessivo, procurou ginecologista. O exame ginecológico revelou apenas útero em AVFM e aumentado para gravidez de 2 meses. A ultrassonografia transvaginal solicitada revelou apenas útero com 180 cc e imagens sugestivas de adenomiose. Isto significa que","options":{"A":"há uma evidente contradição, pois adenomiose é afecção de multíparas. Deve sersolicitada uma ressonância magnética da pelve.","B":"a adenomiose pode explicar o quadro clínico da paciente.","C":"deve ser solicitada uma histeroscopia ambulatorial para avaliação se é umaadenomiose focal ou difusa.","D":"deve ser solicitada a tomografia computadorizada para medida da zona juncional e semaior que 7 mm se confirma o diagnóstico.","E":"a paciente deve ter outra afecção em associação à adenomiose pois o sangramentouterino anormal deve ter outra etiologia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551538","ankiGuid":"oHiwmYUg!S"},{"id":"anki-ginecologia-adenomiose-40ac7cd850608b96","number":"0212g","sourceNumber":"0212g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher, 35 anos, tem uma cesárea prévia e ainda não decidiu se deseja ou não outro filho no futuro, mas sem planos no momento. Há 01 ano com dismenorreia e menorragia importante, ultrassonografia transvaginal demonstra útero discretamente aumentado de volume com borramento da interface endomiometrial, sem outras alterações. Nega comorbidades, mas refere que a mãe teve trombose venosa profunda há 05 anos. Assinale a alternativa que indica a hipótese diagnóstica e melhor forma de tratamento:","options":{"A":"Adenomioma e anticoncepcional oral combinado.","B":"Adenomiose e desogestrel oral.","C":"Endometriose inicial e dienogeste.","D":"Adenomiose e ablação de endométrio."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551539","ankiGuid":"yet?{D=x.$"},{"id":"anki-ginecologia-adenomiose-271df2c1128a7dd9","number":"0213g","sourceNumber":"0213g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente, 35 anos, duas gestações, dois filhos vivos, contracepção com condom, comparece a consulta ginecológica queixando-se de forte dismenorreia e fluxo menstrual aumentado. Realizou ultrassonografia transvaginal que evidenciou útero aumentado de volume, ovários normais e endométrio compatível com a fase do ciclo. É CORRETO afirmar que a hipótese diagnóstica mais provável seja:","options":{"A":"Miomatose uterina.","B":"Síndrome dos ovários policísticos.","C":"Aderências pélvicas.","D":"Adenomiose."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551544","ankiGuid":"yMK#c}/9&k"},{"id":"anki-ginecologia-adenomiose-d6b488cedc331a8e","number":"0214g","sourceNumber":"0214g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Em relação ao métodos de imagem em ginecologia, assinale a alternativa incorreta:","options":{"A":"A ressonância magnética pode quantificar o espessamento da zona juncional nos casos de adenomiose","B":"As calcificações de miomas evidenciadas pela ultrassonografia indicam que o mioma sofreu necrose","C":"A histerossonografia é um método excelente para avaliar cavidade uterina, permeabilidade tubárea e contorno uterino externo","D":"A ultrassonografia está indicada para monitorizar o desenvolvimento folicular, avaliação de anomalias congênitas, rastreamento de malignidade","E":"Os transdutores usados para a ultrassonografia transvaginal tem frequências mais altas que os usados para a ultrassonografia abdominal"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551545","ankiGuid":"g`IcXKrJdQ"},{"id":"anki-ginecologia-adenomiose-29201d70482d989b","number":"0215g","sourceNumber":"0215g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Adenomiose é doença uterina prevalente entre as mulheres, frequentemente associada a sintomas como dismenorréia e sangramento uterino anormal. Em relação aos achados histológicos da adenomiose é frequente a observação de:","options":{"A":"Achados endometriais pré-malignos","B":"Achamos miometriais pré-malignos","C":"Modificação metaplásica endometrial em fibras musculares do útero","D":"Presença de glândulas estromais e estroma endometrial de permeio nas fibras musculares miometriais","E":"Nenhuma das opções acima"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551546","ankiGuid":"BBG8WcW1GW"},{"id":"anki-ginecologia-adenomiose-b68bab68d2d3fa29","number":"0216g","sourceNumber":"0216g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Sobre as doenças miometriais, é correto afirmar que:","options":{"A":"Miomas subserosos, pelo risco de sangramento, devem ser extirpados por videolaparoscopia","B":"A adenomiose é causada por sangramento uterino e é facilmente diagnosticada pelo aumento do útero no toque vaginal","C":"Os miomas são mais frequentes na pós-menopausa","D":"O único tratamento da miomatose é a histerectomia","E":"O mioma submucoso tem ressecção histeroscópica como tratamento preferencial"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551547","ankiGuid":"mPvY!%b,%l"},{"id":"anki-ginecologia-adenomiose-023415ee52213b06","number":"0217g","sourceNumber":"0217g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A dor pélvica crônica tem como uma das causas ginecológicas, a Adenomiose que pode ser caracterizada da seguinte forma, EXCETO:","options":{"A":"A histeroscopia associada à biópsia é exame de confirmação diagnóstica.","B":"Antecedentes de cirurgias uterinas (ginecológicas ou obstétricas são considerados fatores desencadeantes e estão presentes em todos os casos.","C":"O seu quadro clínico pode ser idêntico ao da miomatose uterina.","D":"A RM da pelve é o exame de escolha para o subsídio diagnóstico.","E":"A progesterona é boa opção terapêutica."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551548","ankiGuid":"Qq+T3!NwoH"},{"id":"anki-ginecologia-adenomiose-42cacbeb8f930fb5","number":"0218g","sourceNumber":"0218g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente de 45 anos, G3 P3, com dismenorreia progressiva. Apresenta ainda menstruação com aumento significativo do número de dias e do volume de sangramento no período menstrual. O exame físico revelou um útero aumentado globalmente de volume, com consistência amolecida e útero doloroso à mobilização. De acordo com esse quadro, assinale a alternativa que revela a hipótese diagnóstica mais adequada e a melhor propedêutica para confirmação diagnóstica.","options":{"A":"Mioma, ultrassonografia.","B":"Pólipo, histeroscopia.","C":"Útero didelfo, histerossalpingografia.","D":"Adenomiose, anatomopatológico.","E":"Adenocarcinoma, curetagem."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551549","ankiGuid":"tw6yP/^fOV"},{"id":"anki-ginecologia-adenomiose-3f302ff2e13ffd19","number":"0219g","sourceNumber":"0219g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"São causas de espessamento endometrial na ultrassonografia transvaginal, EXCETO:","options":{"A":"Pólipo","B":"Hiperplasia","C":"Neoplasia","D":"Adenomiose"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551550","ankiGuid":"s4^.;}O]*="},{"id":"anki-ginecologia-adenomiose-dd281d3e5da89d33","number":"0220g","sourceNumber":"0220g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A adenomiose foi referida no passado como cystosarcoma adenoids uterinum. Na maioria das mulheres, os primeiros sintomas podem surgir na adolescência e permanecer na menacme. Em geral, o diagnóstico é feito por achados de histopatologia de peças cirúrgicas. A adenomiose caracteriza-se por","options":{"A":"ser uma condição maligna do útero.","B":"apresentar estroma e glândulas endometriais situadas ectopicamente no miométrio.","C":"ser mais comum em nulíparas do que em multíparas.","D":"apresentar glândulas endometriais no colo uterino, nas tubas e nos ovários."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551551","ankiGuid":"p9W:]HH1[M"},{"id":"anki-ginecologia-adenomiose-2857cb6e2d4c1490","number":"0221g","sourceNumber":"0221g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Com relação a patologias ginecológicas benignas, julgue o próximo item. Mulher multípara que tenha sido submetida a curetagens uterinas pós-aborto apresenta maior risco de adenomiose em comparação a uma mulher nulípara da mesma idade.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551552","ankiGuid":"nqp4#.%|N4"},{"id":"anki-ginecologia-adenomiose-6a100534db63a6be","number":"0222g","sourceNumber":"0222g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A adenomiose é causa de sangramento uterino anormal, e tem como característica:","options":{"A":"O maior risco de sarcoma uterino.","B":"Acometer mulheres jovens nulíparas.","C":"Aumentar o risco de neoplasia maligna do endométrio.","D":"A metaplasia glandular do miométrio.","E":"A presença de glândulas endometriais dentro do miométrio."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551553","ankiGuid":"HOu$je,mki"},{"id":"anki-ginecologia-adenomiose-8a7c826760435735","number":"0223g","sourceNumber":"0223g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente de 45 anos, queixa-se de menstruações volumosas e dismenorreia há seis meses. Hipertensa controlada com hidroclorotizada e losartana. Gesta 1 Para 0, USG transvaginal; aumento de volume uteríno e miométrio heterogêneo, sem configurar nódulos. As alternativas terapêuticas podem ser:","options":{"A":"Ulipristal ou pilula combinada.","B":"Análogo de GnRH ou pilula combinada.","C":"Mifepristone ou análogo do GnRH.","D":"Progestogênio oral ou DIU de levonorgestrel."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551554","ankiGuid":"Q43ocm;muB"},{"id":"anki-ginecologia-adenomiose-7bdd03cc628e0ea9","number":"0224g","sourceNumber":"0224g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Qual patologia é responsável por invasão difusa ou focal do miométrio pelo endométrio benigno, ocorrendo, frequentemente em mulhere acima de 30 anos? (FORTNER, KIMBERLY B; SZYMANSKI, LINDA M; FOX, HAROLD E; WALLACH, EDWARD E. Manual de ginecologia e obstetrícia do Johns Hopkins. Complicações do trabalho de parto e do parto. Editora Artmed. 3ɑ Edição BEREK, JONATHAN S., BEREK E NOVAK – Dor pélvica e dismenorreia.Editora Guanabara-Koogan).","options":{"A":"Miomatose","B":"Cisto de ovário","C":"Cisto de Naboth","D":"Adenomiose","E":"Sarcoma do corpo uterino"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551555","ankiGuid":"w:]E5(J!d_"},{"id":"anki-ginecologia-adenomiose-6da7258d225050ce","number":"0225g","sourceNumber":"0225g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Em relação as patologias benignas do útero, assinale a alternativa INCORRETA.","options":{"A":"Na adenomiose a dismenorréia e sangramento uterino anormal são manifestações clínicas raras, sendo que o diagnóstico em geral se dá por um achado à histerossalpingografia.","B":"Multiparidade é um fator de risco para o diagnóstico de adenomiose.","C":"A maioria das mulheres com leiomioma uterino é assintomática, nestes casos nenhum tratamento a princípio é recomendado.","D":"O leiomioma do tipo subseroso frequentemente é o principal responsável pela compressão pélvica.","E":"Os pólipos endometriais são melhor diagnosticados por histeroscopia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551556","ankiGuid":"y(<KTig/-3"},{"id":"anki-ginecologia-adenomiose-06d23ad777d1f27a","number":"0226g","sourceNumber":"0226g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Assinale a alternativa correto:","options":{"A":"A ressonância magnética é a modalidade de imagem preferencial para a avaliação inicial de massas anexiais.","B":"A vaginose pela Gardnerella é uma condição em que há um predomínio de bactérias aeróbias e não é causa importante de prurido vulvar.","C":"O líquen escleroso é uma inflamação crônica cujo sintoma chave é o prurido vulvar.","D":"A adenomiose é a infiltração profunda do miométrio por tecido endometrial (glandular e estromal) sendo o diagnóstico suspeitado pelos achados histológicos da peça cirúrgica.","E":"A doença inflamatória pélvica caracteriza-se por dor no abdômen inferior, febre e hemograma alterado, sendo o seu diagnóstico fácil e preciso."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551557","ankiGuid":"b=D^HIF{~_"},{"id":"anki-ginecologia-adenomiose-9a3a0c82e5f1c637","number":"0227g","sourceNumber":"0227g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente feminino, 38 anos de idade, G4P3A1 refere que há 3 anos vem apresentando fluxo menstrual abundante (chegando a usar até 6 pacotes de absorventes por ciclo), associado a dismenorreia progressiva e intensa. Ao exame ginecológico, foi notado útero de volume, contorno regular e anexos livres. A ultrassonografia transvaginal mostrou útero de 413 cm³, miométrio heterogêneo difusamente, endométrio de 1,2 cm, ovário direito 3,6 cm³, e ovário esquerdo 4,8 cm³. A biópsia de endométrio foi normal. Assinale a hipótese PROVÁVEL para o caso descrito.","options":{"A":"Miomatose uterina.","B":"Adenomiose.","C":"Sarcoma uterino.","D":"Endometriose."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551558","ankiGuid":"l#%9PpLuV."},{"id":"anki-ginecologia-adenomiose-992ba51a8c366c79","number":"0228g","sourceNumber":"0228g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Sobre as doenças miometriais, é correto afirmar que:","options":{"A":"miomas subserosos, pelo risco de sangramento, devem ser extirpados por videolaparoscopia","B":"a adenomiose é causada por sangramento uterino e é facilmente diagnosticada pelo aumento do útero no toque vaginal","C":"os miomas são mais frequentes na pós-menopausa","D":"o mioma submucoso tem a ressecção histeroscópica como tratamento preferencial"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551559","ankiGuid":"dTiZ<xlD}z"},{"id":"anki-ginecologia-adenomiose-0ecc578ffd57a9b7","number":"0229g","sourceNumber":"0229g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Leia o caso clínico a seguir. Uma paciente multípara, de 45 anos, apresentou sangramento uterino anormal há aproximadamente oito meses. O exame ginecológico evidencia útero aumentado de volume e globoso. A paciente refere dismenorreia intensa associada. Nesse caso, qual é o diagnóstico mais provável?","options":{"A":"Câncer de colo uterino","B":"Adenomiose","C":"Endometriose.","D":"Doença inflamatória pélvica aguda."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551560","ankiGuid":"pC&E=Q4Wth"},{"id":"anki-ginecologia-adenomiose-6ef7be6927c4f1d2","number":"0230g","sourceNumber":"0230g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Sobre a Adenomiose, assinale a alternativa correta:","options":{"A":"O padrão ouro no diagnóstico é a laparoscopia.","B":"Os sintomas mais comuns são dismenorreia e amenorréia.","C":"É mais frequente em multíparas que em nuliparas.","D":"É mais comum em pacientes na faixa dos 30 anos de idade."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551561","ankiGuid":"k+EYu.(N5v"},{"id":"anki-ginecologia-adenomiose-fa99a3badd0df665","number":"0231g","sourceNumber":"0231g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Priscila, 37 anos, com queixa de aumento do fluxo menstrual e cólicas menstruais há 4 anos, com piora progressiva. No momento, fluxo menstrual com 8 dias de duração e cólica menstrual intensa por 10 dias, ciclos com duração de 30 dias. Uso de anti- inflamatórios sem alívio da dor. GIII PIII (3 cesarianas). Exame físico: hipocorada ++/+4; IMC = 25 kg/m²; exame abdominal sem alterações. Exame especular sem alterações. Toque com útero em anteversoflexão, móvel, globoso, indolor à mobilização, anexos impalpáveis. Marque a opção que confere a principal hipótese diagnóstica e seu respectivo tratamento.","options":{"A":"Miomatose uterina – miomectomia.","B":"Anovulação – pílula anticoncepcional combinada ou somente com progesterona.","C":"Endometriose – laparoscopia.","D":"Adenomiose – pílula anticoncepcional combinada ou somente com progesterona."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551562","ankiGuid":"s5BWRNP/&z"},{"id":"anki-ginecologia-adenomiose-c25c9dd6f597c710","number":"0232g","sourceNumber":"0232g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Paciente de 42 anos procura a emergência de atendimento ginecológico por apresentar sangramento uterino intenso no período menstrual, dismenorreia intensa agravada no último ano e dispareunia, que torna a atividade sexual um grande sofrimento pela dor. O grupo em que essa doença pode ser considerada pela classificação PALM-COEIM, de acordo com a FIGO, o diagnóstico e a alteração uterina que pode ser encontrada no exame de toque vaginal são, respectivamente:","options":{"A":"grupo de PALM, diagnóstico de leiomioma, útero de consistência amolecida.","B":"grupo de PALM, diagnóstico de adenomiose, útero doloroso e superfície lisa.","C":"grupo de COEIM, diagnóstico de endometriose, útero doloroso.","D":"grupo de COEIM, diagnóstico de câncer de endométrio avançado, útero de tamanho normal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551563","ankiGuid":"BiOrhPk:q^"},{"id":"anki-ginecologia-adenomiose-35f31da366ea4eca","number":"0233g","sourceNumber":"0233g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 45 anos, gesta 2 para 2 (cesáreas), submetida a laqueadura tubária no segundo parto, apresentando dismenorreia secundária e aumento do fluxo menstrual (menorragia). Ao toque, observa-se útero difusamente aumentado, com boa mobilidade, sem dor à mobilização. Ao ultrassom endovaginal evidencia-se útero aumentado (198 cm3) e 1 nódulo de 9x9 mm subseroso, fúndico que pode corresponder a mioma. A mais provável causa dos sintomas referidos é:","options":{"A":"Adenomiose.","B":"O mioma referido no ultrassom.","C":"Endometriose.","D":"Pelviperitonite."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551564","ankiGuid":"QQUvk[XI:@"},{"id":"anki-ginecologia-adenomiose-f0970bb22ec248da","number":"0234g","sourceNumber":"0234g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 40 anos, com prole definida, apresentando dismenorreia secundária há 6 meses, associada a aumento da duração e do fluxo menstrual. Exame clínico e ultrassonográfico: aumento uterino difuso, sugestivo de adenomiose. A melhor conduta é:","options":{"A":"Histerectomia.","B":"AINEs.","C":"Ablação endometrial.","D":"Análogos de GnRH."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551565","ankiGuid":"j+:S6)<yrE"},{"id":"anki-ginecologia-adenomiose-fff47bc882066b12","number":"0235g","sourceNumber":"0235g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Em uma paciente de 44 anos, Gesta 3 Para 3, que cursa com dismenorreia secundária progressiva e aumento do fluxo menstrual, qual é a causa mais provável nesse caso?","options":{"A":"Leiomioma.","B":"Sarcoma.","C":"Adenomiose.","D":"Endometriose."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551566","ankiGuid":"Aw]8Qc&Vm}"},{"id":"anki-ginecologia-adenomiose-934ca5faee23a7af","number":"0236g","sourceNumber":"0236g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Caracteriza a histopatologia da adenomiose:","options":{"A":"A presença de glândulas endometriais e estroma de permeio ao miométrio.","B":"Modificação metaplásica do epitélio glandular em fibras musculares no útero.","C":"Uma alteração pré-maligna do miométrio.","D":"O mesmo padrão histológico e localização da endometriose.","E":"Uma alteração pré-maligna do endométrio."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551567","ankiGuid":"gw-1F;LMA0"},{"id":"anki-ginecologia-adenomiose-c2e27fe3a7f0a3d6","number":"0237g","sourceNumber":"0237g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Sobre adenomiose marque a alternativa CORRETA:","options":{"A":"Caracteriza-se pela presença de glândulas e estroma endometriais localizados superficialmente entre as fibras do miométrio.","B":"Pode ser classificada de acordo com a profundidade do comprometimento miometrial. Grau 1: acomete 1/3 do miométrio; grau 2: acomete 2/3 do miométrio; grau 3: acomete todo o miométrio.","C":"As formas mais comuns de apresentação são a nodular (adenomioma) e cística.","D":"O tratamento de 1ª escolha para mulheres com desejo reprodutivo é a Embolização das artérias uterinas.","E":"Está contraindicado o sistema intrauterino liberador de levonorgestrel (Mirena®) em paciente com adenomiose."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551568","ankiGuid":"d?,{AaQIp5"},{"id":"anki-ginecologia-adenomiose-407738ff1c193b50","number":"0238g","sourceNumber":"0238g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Lia, 45 anos, nuligesta, apresenta queixa de cólicas menstruais de forte intensidade associada à irregularidade menstrual e alto fluxo há oito anos, com piora progressiva. Já fez uso de anticoncepcionais orais combinados com pausa sem sucesso terapêutico. A ultrassonografia indicou heterogeneidade miometrial, além de projeções estriadas lineares estendendo-se do endométrio para o interior do miométrio, sugerindo diagnóstico de adenomiose. A partir disso, assinale a alternativa INCORRETA:","options":{"A":"A maioria dos casos de adenomiose ocorre em pacientes com filhos.","B":"O uso de dispositivo intrauterino hormonal é boa opção terapêutica.","C":"A ablação endometrial é opção indicada para pacientes que ainda desejam engravidar.","D":"A minoria das pacientes com adenomiose são sintomáticas.","E":"A histerectomia é o tratamento definitivo para adenomiose."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551569","ankiGuid":"B*S8wkeDU<"},{"id":"anki-ginecologia-adenomiose-e9b43340864d9f31","number":"0239g","sourceNumber":"0239g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Em paciente de 45 anos, nuligesta com suspeita clínica de adenomiose, o exame complementar “padrão ouro” para a confirmação diagnóstica será:","options":{"A":"Ultrassonografia endovaginal com doppler colorido.","B":"RNM.","C":"Ultrassonografia com preparo intestinal.","D":"Histeroscopia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551570","ankiGuid":"jy6[L6!-|v"},{"id":"anki-ginecologia-adenomiose-ee7de20e04c4768e","number":"0240g","sourceNumber":"0240g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 44 anos, 6 Gesta, 6 Para, refere aumento do fluxo menstrual há um ano. Os ciclos são regulares a cada 28 dias e a duração é de 6 dias. No exame físico, observa-se o útero aumentado de tamanho em cerca de três vezes, superfície regular, móvel. Anexos normais. A ultrassonografia pélvica revela útero globalmente aumentado, com ecotextura difusamente heterogênea, com volume de 300 cm³, eco endometrial homogêneo com espessura de 7 mm e ovários normais. A causa mais provável da queixa clínica é:","options":{"A":"Pólipo uterino.","B":"Endometriose.","C":"Sangramento disfuncional.","D":"Mioma uterino.","E":"Adenomiose."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551571","ankiGuid":"o;b%PK3&-d"},{"id":"anki-ginecologia-adenomiose-fcba572f96f72ecf","number":"0241g","sourceNumber":"0241g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"A adenomiose:","options":{"A":"Pode ser assintomática e não se associa à miomatose uterina e à endometriose.","B":"Causa aumento exagerado do volume uterino e corrimento vaginal.","C":"Causa sangramentos menstruais intensos e dolorosos durante a vida reprodutiva.","D":"Não provoca sintomas com a menstruação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551572","ankiGuid":"dmm82$l{5C"},{"id":"anki-ginecologia-adenomiose-828fd17ed67aa7ec","number":"0242g","sourceNumber":"0242g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Mulher de 42 anos procura atendimento com queixa de sangramento menstrual anormal caracterizado pelo aumento dos dias e da quantidade do fluxo, há dois anos, com piora nos últimos meses, associado à dismenorreia progressiva. Tem antecedentes de três partos normais, laqueadura tubária há dez anos, sem nenhuma comorbidade. Nega dispareunia e sinusiorragia. Diante desse quadro, a principal hipótese diagnóstica é:","options":{"A":"hemorragia uterina disfuncional.","B":"endometriose.","C":"adenomiose.","D":"hemorragia da perimenopausa."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551573","ankiGuid":"z<58N~b,!S"},{"id":"anki-ginecologia-adenomiose-0d3df69065d5f4b6","number":"0243g","sourceNumber":"0243g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"É patologia ginecológica mais comum na quarta década de vida, que acarreta útero globalmente aumentado de volume, dismenorreia e hipermenorreia:","options":{"A":"Adenomiose.","B":"Endometriose.","C":"Miomatose uterina.","D":"Pólipo endometrial.","E":"Sarcoma uterino."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551574","ankiGuid":"JHJRysBc~S"},{"id":"anki-ginecologia-adenomiose-6e4f377bb5295bc1","number":"0244g","sourceNumber":"0244g","collectionBlock":"anki:ginecologia-adenomiose","collectionLabel":"Anki · Adenomiose","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Adenomiose","subtopic":"","stem":"Após consulta ginecológica e realização de ultrassonografia, um paciente de 35 anos recebe diagnóstico de adenomiose. Para realização do diagnostico qual dos dados a seguir é mais consistente na historia clinico da paciente.","options":{"A":"Infertilidade conjugal.","B":"Micção dolorosa.","C":"Sangramento uterino anormal e dismenorreia.","D":"Volume uterino aumentado e miométrio hidrogênio ao USG."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Adenomiose","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Adenomiose","Anki"],"ankiNoteId":"1779734551575","ankiGuid":"r;y2!2@YB|"}]};
